+import { describe, it, expect } from "vitest"
+
+const GHE = "ghe.example.com"
+process.env.GITHUB_HOSTS = GHE
+
+describe("parseIssueUrl", () => {
+  const ok = (u:string, host=undefined as undefined|string) => {
+    it(`accepts ${u}`, () => {
+      const p = parseIssueUrl(u)
+      expect(p.issueNumber).toBeGreaterThan(0)
+      if (host) expect(p.host).toBe(host)
+    })
+  }
+  const bad = (u:string) => {
+    it(`rejects ${u}`, () => {
+      expect(() => parseIssueUrl(u)).toThrow(InvalidIssueUrlError)
+    })
+  }
+
+  ok("https://github.com/o/r/issues/12")
+  ok("https://github.com/o/r/issues/12/")
+  ok("https://github.com/o/r/issues/12?x=1#y")
+  ok("https://www.github.com/o/r/issues/12")
+  ok(`https://${GHE}/o/r/issues/99`, GHE)
+
+  bad("http://github.com/o/r/issues/12")
+  bad("https://github.com/o/r/pull/12")
+  bad("https://github.com/o/r/issues/0")
+  bad("https://github.com/o/r/issues/abc")
+  bad("https://unknown.com/o/r/issues/12")
+})
