 import { Octokit } from "octokit";
 import logger from "../logger.js";

+export class InvalidIssueUrlError extends Error {}
+
+export function parseIssueUrl(issueUrl: string): { host: string; owner: string; repo: string; issueNumber: number } {
+    try {
+        const u = new URL(issueUrl)
+        if (u.protocol !== "https:") throw new InvalidIssueUrlError("Only https URLs are supported")
+        // strip www.
+        const host = u.hostname.replace(/^www\./, "")
+        const allowed = ["github.com"]
+        const extra = process.env.GITHUB_HOSTS ?? ""
+        for (const h of extra.split(",").map(s=>s.trim()).filter(Boolean)) allowed.push(h)
+        if (!allowed.includes(host)) throw new InvalidIssueUrlError("Unknown host: " + host)
+        // pathname like /owner/repo/issues/123 or with trailing slash
+        const parts = u.pathname.replace(/(^\/|\/$)/g, "").split("/")
+        // Expect at least owner/repo/issues/number
+        if (parts.length < 4) throw new InvalidIssueUrlError("Invalid issue URL")
+        const [owner = "", repo = "", segment = "", numberStr = ""] = parts
+        if (segment !== "issues") throw new InvalidIssueUrlError("URL is not an issue URL")
+        if (!/^[A-Za-z0-9_.-]+$/.test(owner) || !/^[A-Za-z0-9_.-]+$/.test(repo)) throw new InvalidIssueUrlError("Invalid owner or repo name")
+        if (!/^[0-9]+$/.test(numberStr)) throw new InvalidIssueUrlError("Issue number is not numeric")
+        const issueNumber = parseInt(numberStr, 10)
+        if (issueNumber <= 0) throw new InvalidIssueUrlError("Issue number must be greater than zero")
+        return { host, owner, repo, issueNumber }
+    } catch (err) {
+        if (err instanceof InvalidIssueUrlError) throw err
+        throw new InvalidIssueUrlError("Invalid issue URL")
+    }
+}
